import sys
from collections import defaultdict

def get_pieces(picture, X, Y):
    pieces = set()
    for i in range(0, A, X):
        for j in range(0, B, Y):
            piece = []
            for x in range(X):
                for y in range(Y):
                    piece.append(picture[i + x][j + y])
            piece_str = ''.join(piece)
            min_rotated_piece = min(piece_str, piece_str[::-1], ''.join(piece[k::Y] for k in range(Y)), ''.join(piece[k::Y][::-1] for k in range(Y)))
            pieces.add(min_rotated_piece)
    return pieces

A, B = map(int, sys.stdin.readline().split())
picture = [sys.stdin.readline().strip() for _ in range(A)]

good_puzzles = []
for X in range(1, A + 1):
    if A % X != 0:
        continue
    for Y in range(1, B + 1):
        if B % Y != 0:
            continue
        pieces = get_pieces(picture, X, Y)
        if len(set(pieces)) == (A // X) * (B // Y):
            good_puzzles.append((X, Y))

number_of_good_puzzles = len(good_puzzles)
smallest_puzzle_size = min(good_puzzles, key=lambda x: (x[0] * x[1], x[0]))

print(number_of_good_puzzles)
print(smallest_puzzle_size[0], smallest_puzzle_size[1])
